import{_ as t,o as a,c as i,a9 as r}from"./chunks/framework.AY-u9rel.js";const u=JSON.parse('{"title":"Application Profiles and Starter Kits","description":"Choose an application profile or starter kit when creating a Feluqa application.","frontmatter":{"sidebarTitle":"Starter Kits","icon":"layers-3","title":"Application Profiles and Starter Kits","description":"Choose an application profile or starter kit when creating a Feluqa application.","summary":"Explains that a Feluqa starter kit is selected as an application profile when creating an application, using the `feluqa new <app> profile <profile-or-starter-kit>` command shape. It distinguishes the selected profile or starter kit from the executable binary, Rust compilation target, and interaction surface, and marks tooling that is not yet available.","weight":6,"tags":["feluqa","getting-started","profiles","targets"],"date":"2026-10-29T00:00:00.000Z","lastmod":"2026-10-29T00:00:00.000Z","status":"Exploring","draft":true,"author":{"name":"El Moumen Yassine","url":"https://numerimondes.com","linkedin":"https://www.linkedin.com/in/elmoumenyassine","email":"yassine@numerimondes.com"}},"headers":[],"relativePath":"get-started/starter-kits/application-profiles-and-starter-kits.md","filePath":"get-started/starter-kits/application-profiles-and-starter-kits.md"}'),o={name:"get-started/starter-kits/application-profiles-and-starter-kits.md"};function n(s,e,l,p,c,d){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="application-profiles-and-starter-kits" tabindex="-1">Application Profiles and Starter Kits <a class="header-anchor" href="#application-profiles-and-starter-kits" aria-label="Permalink to &quot;Application Profiles and Starter Kits&quot;">​</a></h1><p>A starter kit is an application profile selected when creating a new application. The command shape is:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>feluqa new &lt;app&gt; profile &lt;profile-or-starter-kit&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Here, <code>&lt;app&gt;</code> names the new application and the final argument selects the profile or starter kit that provides its initial structure and configuration. The available profiles and starter kits depend on what Feluqa provides. This command workflow is planned; the current CLI syntax is documented with the commands that are available today.</p><p>When you create an application, three related choices may appear: what kind of application you are building, which executable starts it, and which platform Rust compiles it for. They answer different questions.</p><h2 id="application-profile" tabindex="-1">Application profile <a class="header-anchor" href="#application-profile" aria-label="Permalink to &quot;Application profile&quot;">​</a></h2><p>An application profile describes the kind of Feluqa application and runtime it uses, such as web or workstation. A product may eventually support more than one profile while sharing its business modules and other Rust code. Feluqa&#39;s target architecture uses separate runtimes for different targets.</p><p>The project configuration should declare which profiles an application supports. Feluqa&#39;s project tooling can then use that declaration to select and validate the appropriate runtime and build workflow. This project-level configuration and multi-profile workflow are planned capabilities; the current scaffold does not yet provide them.</p><h2 id="executable-binary" tabindex="-1">Executable binary <a class="header-anchor" href="#executable-binary" aria-label="Permalink to &quot;Executable binary&quot;">​</a></h2><p>A binary is an executable entry point declared in <code>Cargo.toml</code>. A console application, such as the <code>hello-cli</code> example, has a binary name and starts a Feluqa console profile that registers its commands. The binary declaration does not by itself identify a web or workstation runtime.</p><h2 id="rust-compilation-target" tabindex="-1">Rust compilation target <a class="header-anchor" href="#rust-compilation-target" aria-label="Permalink to &quot;Rust compilation target&quot;">​</a></h2><p>The Rust compilation target identifies the platform and architecture for the compiled program, for example a native operating system target or a WebAssembly target. Cargo receives this choice as part of the build configuration. It is separate from the product&#39;s application profile: a profile describes the application/runtime, while the compilation target describes where the resulting program runs.</p><p>The interaction surface is another independent choice. A console application could run in a traditional terminal, in a future desktop host that presents it as a terminal-style window, or as part of a graphical desktop application with an integrated terminal. These desktop host experiences are product directions; they are not currently available in Feluqa.</p><h2 id="where-should-the-choice-live" tabindex="-1">Where should the choice live? <a class="header-anchor" href="#where-should-the-choice-live" aria-label="Permalink to &quot;Where should the choice live?&quot;">​</a></h2><p>Declare the application&#39;s supported profiles through Feluqa project configuration when that configuration is available. Keep the Rust compilation target in the Cargo build workflow. A build script may read project settings, validate them, or generate code, but it should not be the only place that declares what kind of application the project is.</p><p>For the first CLI example, no extra application-type attribute is needed: its <code>Cargo.toml</code> declares the binary, and its <code>main.rs</code> declares the console profile. See <a href="/get-started/directory-structure/cli-structure">How a Feluqa CLI Is Structured</a>.</p><h2 id="continue" tabindex="-1">Continue <a class="header-anchor" href="#continue" aria-label="Permalink to &quot;Continue&quot;">​</a></h2><p>You have now seen how to choose and distinguish the application profile, binary, compilation target, and interaction surface. Continue with the <a href="/get-started/introduction/architecture-overview">Feluqa architecture overview</a> for Feluqa&#39;s target architecture.</p>',18)])])}const f=t(o,[["render",n]]);export{u as __pageData,f as default};
